<div class="scan-workspace" data-scanner-workspace data-action="/shows/<?= e($show['id']) ?>/return" data-kind="return"><div class="page-heading"><div><p class="eyebrow"><?= e($show['name']) ?></p><h1><?= $mode==='barcode'?'Barcode return station':'Manual equipment returns' ?></h1><p class="text-secondary">Condition is recorded per return operation. Broken or missing-parts assets automatically open repair tickets.</p></div><button class="btn" type="button" data-fullscreen>Fullscreen</button></div>
<section class="card floating-card" data-card-key="return-station"><h2 class="floating-label"><span class="material-symbols-rounded" aria-hidden="true">assignment_return</span>Return equipment</h2><div class="card-body">
