<?php else: ?><?php foreach ($lines as $line): ?><label class="manual-row"><span><strong><?= e($line['name']) ?></strong><small><?= e($line['quantity']) ?> outstanding</small></span><input type="number" class="form-control" name="quantities[<?= e($line['id']) ?>]" min="0" max="<?= e($line['quantity']) ?>" value="0" aria-label="Return quantity for <?= e($line['name']) ?>"></label><?php endforeach; ?><button class="btn btn-primary mt-3">Save return</button><?php endif; ?>
<div class="form-error" role="alert" hidden></div></form><div class="component-loader" role="status" hidden><span class="spinner-border spinner-border-sm"></span>Recording return...</div><div data-scan-feedback class="scan-feedback" aria-live="assertive"></div></div></section>
<section class="card floating-card" data-card-key="return-outstanding"><h2 class="floating-label">Outstanding equipment</h2><div class="card-body"><?php if (!$lines): ?><p>All equipment has been returned or transferred.</p><?php endif; ?><?php foreach ($lines as $line): ?><div class="record-row" data-outstanding-type="<?= e($line['id']) ?>"><strong><?= e($line['name']) ?></strong><span data-outstanding-quantity><?= e($line['quantity']) ?></span></div><?php endforeach; ?></div></section></div>
